/*
 * Dataset-replay bench -- the board with no microphone.
 *
 * Real HLS-CMDS mixtures are compiled into flash (lib/hls_filter/hls_clips.h,
 * generated by tools/embed_clips.py). This firmware replays them through the
 * same band split the mic firmwares use, times the filtering, and streams the
 * result back so the host can score it.
 *
 * The point of doing it this way: the samples on the board are bit-identical to
 * the ones src/baseline/baseline1.py filters, so the board's output can be
 * diffed against scipy exactly and its SDR compared straight to the numbers in
 * results/. A microphone would make that impossible -- different transducer,
 * different gain, no ground truth.
 *
 * The decimator is NOT in this path: the dataset is already at 4000 Hz. Only
 * the two bandpass cascades run.
 *
 * Send a byte to start:
 *   's' -- stream the filtered output back as binary (tools/run_on_device.py)
 *   anything else -- timing only, human-readable (pio device monitor, press Enter)
 */
#include <Arduino.h>

#include "hls_clips.h"
#include "hls_filter.h"
#include "hls_stream.h"

/* Output is streamed per block, so RAM does not scale with clip length. */
#define BENCH_BLOCK 256u

static hls_biquad_t heart_filter;
static hls_biquad_t lung_filter;
static float in_block[BENCH_BLOCK];
static float heart_block[BENCH_BLOCK];
static float lung_block[BENCH_BLOCK];

static void write_record(const void *record, size_t size)
{
    Serial.write((const uint8_t *)record, size);
}

/*
 * Returns the filtering time in microseconds -- int16 scaling plus both band
 * cascades. Serial writes sit outside the timed region on purpose: this number
 * is meant to replace the desktop figures in src/latency.py, so it must measure
 * compute, not USB.
 */
static uint32_t run_clip(const hls_clip_t *clip, bool stream)
{
    hls_biquad_init(&heart_filter, HLS_HEART_SOS, (uint8_t)HLS_HEART_SECTIONS);
    hls_biquad_init(&lung_filter, HLS_LUNG_SOS, (uint8_t)HLS_LUNG_SECTIONS);

    if (stream) {
        hls_clip_header_t header;
        memcpy(header.magic, HLS_CLIP_MAGIC, sizeof(header.magic));
        memset(header.clip_id, 0, sizeof(header.clip_id));
        strncpy(header.clip_id, clip->id, sizeof(header.clip_id) - 1);
        header.n_samples = clip->n_samples;
        header.sample_rate = HLS_CLIP_SR_HZ;
        write_record(&header, sizeof(header));
    }

    uint32_t compute_micros = 0;
    uint16_t seq = 0;

    for (uint32_t off = 0; off < clip->n_samples; off += BENCH_BLOCK) {
        uint32_t chunk = clip->n_samples - off;
        if (chunk > BENCH_BLOCK) {
            chunk = BENCH_BLOCK;
        }

        const uint32_t t0 = micros();
        for (uint32_t i = 0; i < chunk; ++i) {
            in_block[i] = (float)clip->samples[off + i] * (1.0f / 32768.0f);
        }
        hls_biquad_process(&heart_filter, in_block, heart_block, chunk);
        hls_biquad_process(&lung_filter, in_block, lung_block, chunk);
        compute_micros += micros() - t0;

        if (stream) {
            hls_frame_header_t frame;
            memcpy(frame.magic, HLS_STREAM_MAGIC, sizeof(frame.magic));
            frame.n_samples = (uint16_t)chunk;
            frame.seq = seq++;
            frame.dropped = 0u;
            write_record(&frame, sizeof(frame));
            write_record(heart_block, chunk * sizeof(float));
            write_record(lung_block, chunk * sizeof(float));
        }
    }

    if (stream) {
        hls_clip_footer_t footer;
        memcpy(footer.magic, HLS_FOOTER_MAGIC, sizeof(footer.magic));
        footer.n_samples = clip->n_samples;
        footer.compute_micros = compute_micros;
        write_record(&footer, sizeof(footer));
    }
    return compute_micros;
}

static void print_summary(const hls_clip_t *clip, uint32_t compute_micros)
{
    const float audio_seconds = (float)clip->n_samples / (float)HLS_CLIP_SR_HZ;
    const float compute_ms = compute_micros / 1000.0f;

    Serial.print("# ");
    Serial.print(clip->id);
    Serial.print("  ");
    Serial.print(clip->n_samples);
    Serial.print(" samples (");
    Serial.print(audio_seconds, 2);
    Serial.print(" s)  compute ");
    Serial.print(compute_ms, 3);
    Serial.print(" ms  ");
    Serial.print(compute_micros / (float)clip->n_samples, 3);
    Serial.print(" us/sample  real-time factor ");
    Serial.println(audio_seconds * 1.0e6f / (float)compute_micros, 1);
}

void setup()
{
    Serial.begin(115200);
#if defined(ARDUINO_ARCH_MBED)
    while (!Serial) {
        ;  /* native USB CDC */
    }
#else
    delay(200);
#endif

    Serial.println("# hls_filter dataset-replay bench");
    Serial.print("# backend: ");
#if defined(HLS_FILTER_BACKEND_CMSIS)
    Serial.println("CMSIS-DSP arm_biquad_cascade_df2T_f32");
#elif defined(HLS_FILTER_BACKEND_ESPDSP)
    Serial.println("ESP-DSP dsps_biquad_f32");
#else
    Serial.println("portable C");
#endif
    Serial.print("# ");
    Serial.print(HLS_CLIP_COUNT);
    Serial.print(" clip(s) at ");
    Serial.print(HLS_CLIP_SR_HZ);
    Serial.println(" Hz, causal single-pass IIR, no decimation (dataset is already 4 kHz)");
    /* Repeat the prompt until someone answers. A host that opens the port after
     * the board has already booted would otherwise miss a single printed prompt
     * and sit waiting for a banner that will never come again. */
    Serial.println("# send 's' to stream filtered output, any other byte for timing only");
    uint32_t last_prompt = millis();
    while (!Serial.available()) {
        if (millis() - last_prompt >= 1000u) {
            Serial.println("# send 's' to stream filtered output, any other byte for timing only");
            last_prompt = millis();
        }
    }
    const bool stream = (Serial.read() == 's');
    while (Serial.available()) {
        Serial.read();  /* drop the rest of the line so it is not read as data */
    }

    uint32_t totals[HLS_CLIP_COUNT];
    for (uint32_t i = 0; i < HLS_CLIP_COUNT; ++i) {
        totals[i] = run_clip(&HLS_CLIPS[i], stream);
    }

    if (stream) {
        hls_done_t done;
        memcpy(done.magic, HLS_DONE_MAGIC, sizeof(done.magic));
        done.clip_count = HLS_CLIP_COUNT;
        write_record(&done, sizeof(done));
    }

    /* Text only after the done record, so a host parser has a clean stop point. */
    Serial.println();
    for (uint32_t i = 0; i < HLS_CLIP_COUNT; ++i) {
        print_summary(&HLS_CLIPS[i], totals[i]);
    }
    Serial.println("# done");
}

void loop()
{
    delay(1000);
}
